"""Thirty spin-preserving singles and the original bounded VQE experiment."""

import math
from dataclasses import dataclass

import torch

import flagquantum as fq
from examples.synthesis.applications.chemistry.lih_chemistry.overview.variational import (
    ansatz,
)
from flagquantum.algorithms import CobylaOptimizer
from flagquantum.algorithms.fermion.encoding import encode_fermion
from flagquantum.algorithms.fermion.lowering import lift_stabilizer_state
from flagquantum.algorithms.fermion.observables import to_observable
from flagquantum.core.algebra.pauli import PauliOperator
from flagquantum.observables.fermion import annihilate, create

from .model import OCCUPIED, WIDTH, Model, trim

PAIRS = tuple(
    (2 * occupied + spin, 2 * virtual + spin)
    for occupied in range(OCCUPIED)
    for virtual in range(OCCUPIED, WIDTH // 2)
    for spin in range(2)
)
BUDGET, TOLERANCE = 100, 1e-4


@dataclass(frozen=True)
class Trial:
    parameters: tuple[float, ...]
    energy: float


@dataclass(frozen=True)
class Optimization:
    trace: tuple[Trial, ...]
    selected: Trial
    physical_trimmed_energy: float
    physical_untrimmed_energy: float
    converged: bool
    query_budget_reached: bool


class QueryBudgetError(Exception):
    """Stop before an unapproved one-hundred-and-first actual objective."""


def operators(model: Model) -> tuple[PauliOperator, ...]:
    result = []
    for occupied, virtual in PAIRS:
        excitation = create(occupied) * annihilate(virtual)
        generator = 1j * (excitation - excitation.dagger())
        encoded = encode_fermion(generator, n_modes=WIDTH).operator
        result.append(trim(model.reduction.reduce_operator(encoded), 1e-12))
    return tuple(result)


def circuit(
    model: Model,
    generators: tuple[PauliOperator, ...],
    parameters: tuple[float, ...],
) -> fq.Circuit:
    if len(generators) != 30 or len(parameters) != 30:
        raise ValueError("The original singles ansatz requires thirty angles")
    if not all(math.isfinite(value) for value in parameters):
        raise ValueError("The singles parameters must be finite")
    return ansatz(14, model.hf_word, generators, parameters)


def independent_occupation_state(parameters: tuple[float, ...]) -> torch.Tensor:
    """Apply signed two-determinant rotations without Pauli mapping or lowering."""
    indices = torch.arange(1 << WIDTH)
    state = torch.zeros(1 << WIDTH, dtype=torch.complex128)
    state[((1 << 10) - 1) << 6] = 1
    for (occupied, virtual), angle in zip(PAIRS, parameters, strict=True):
        occupied_mask, virtual_mask = 1 << (15 - occupied), 1 << (15 - virtual)
        source = indices[
            ((indices & occupied_mask) == 0) & ((indices & virtual_mask) != 0)
        ]
        target = source ^ occupied_mask ^ virtual_mask
        parity = torch.zeros_like(source)
        for mode in range(occupied + 1, virtual):
            parity ^= (source >> (15 - mode)) & 1
        sign = (1 - 2 * parity).to(torch.float64)
        a, b = state[source].clone(), state[target].clone()
        state[source] = math.cos(angle) * a - sign * math.sin(angle) * b
        state[target] = sign * math.sin(angle) * a + math.cos(angle) * b
    return state


def check_states(
    model: Model, generators: tuple[PauliOperator, ...]
) -> tuple[float, ...]:
    errors = []
    for scale in (0.17, -0.23):
        angles = tuple(scale * (index + 1) / 30 for index in range(30))
        reduced = circuit(model, generators, angles).state().reshape(-1)
        actual = lift_stabilizer_state(model.reduction, reduced)
        expected = independent_occupation_state(angles)
        errors.append(float((actual - expected).abs().max()))
    if max(errors) > 1e-12:
        raise ValueError(
            "The complete singles states disagree with occupation rotations"
        )
    return tuple(errors)


def optimize(model: Model, generators: tuple[PauliOperator, ...]) -> Optimization:
    cost = to_observable(model.trimmed)
    trace: list[Trial] = []

    def evaluate(point: torch.Tensor) -> torch.Tensor:
        if len(trace) >= BUDGET:
            raise QueryBudgetError
        angles = tuple(float(value) for value in point)
        result = fq.run(
            circuit(model, generators, angles), outputs=[fq.expectation(cost)]
        )
        value = torch.as_tensor(result.expectation()).reshape(-1).sum().real
        trace.append(Trial(angles, float(value)))
        return value

    converged = stopped = False
    try:
        result = CobylaOptimizer(maxiter=BUDGET, rhobeg=1, rhoend=TOLERANCE).minimize(
            evaluate, torch.zeros(30, dtype=torch.float64)
        )
        converged = result.converged
    except QueryBudgetError:
        stopped = True
    selected = min(trace, key=lambda trial: trial.energy)
    physical = fq.run(
        circuit(model, generators, selected.parameters),
        outputs=[fq.expectation(to_observable(model.physical_trimmed))],
    )
    energy = float(torch.as_tensor(physical.expectation()).reshape(-1).sum().real)
    full = fq.run(
        circuit(model, generators, selected.parameters),
        outputs=[fq.expectation(to_observable(model.reduction.operator))],
    )
    untrimmed = float(torch.as_tensor(full.expectation()).reshape(-1).sum().real)
    return Optimization(tuple(trace), selected, energy, untrimmed, converged, stopped)

"""Run the tapered first-order UCCSD ansatz with a checked local objective."""

import itertools
import math
from dataclasses import dataclass

import torch

import flagquantum as fq
from flagquantum.algorithms import CobylaOptimizer
from flagquantum.algorithms.fermion.clifford import pauli_words_commute
from flagquantum.algorithms.fermion.encoding import encode_fermion
from flagquantum.algorithms.fermion.numerics import pauli_matrix
from flagquantum.core.algebra.pauli import PauliOperator, PauliTerm
from flagquantum.observables.fermion import FermionOperator, annihilate, create

from .model import ACTIVE_ORBITALS, WIDTH
from .symmetry import Sectors, trim

BUDGET = 200
THRESHOLD = 1e-3


@dataclass(frozen=True)
class Trial:
    energy: float
    parameters: tuple[float, ...]


@dataclass(frozen=True)
class Optimization:
    terms: int
    width: int
    excitation_terms: tuple[int, ...]
    probes: tuple[Trial, ...]
    convergence: bool
    budget_stop: bool
    state_error: float


class QueryBudgetError(Exception):
    """Bound actual local objectives at the source's iteration configuration."""


def _bare_excitation(
    source: tuple[int, ...], target: tuple[int, ...]
) -> FermionOperator:
    operator = create(source[0])
    for wire in source[1:]:
        operator *= create(wire)
    for wire in target:
        operator *= annihilate(wire)
    return (1j / math.factorial(len(source))) * (operator - operator.dagger())


def excitation_operators(sectors: Sectors) -> tuple[PauliOperator, ...]:
    allowed = tuple(
        (spin, 2 * orbital + spin)
        for spin in range(2)
        for orbital in range(1, ACTIVE_ORBITALS)
    )
    outputs = []
    for rank in (1, 2):
        for group in itertools.combinations(allowed, rank):
            source, target = zip(*group, strict=True)
            if len(set(source)) != rank or len(set(target)) != rank:
                continue
            candidate = _bare_excitation(source, target)
            pauli_op = encode_fermion(candidate, n_modes=WIDTH).operator
            preserving = PauliOperator(
                tuple(
                    term
                    for term in pauli_op.terms
                    if all(
                        pauli_words_commute(term, gen.terms[0])
                        for gen in sectors.generators
                    )
                )
            )
            reduced = trim(sectors.reduction.reduce_operator(preserving), 1e-12)
            if any(term.factors for term in reduced.terms):
                outputs.append(reduced)
    return tuple(outputs)


def append_factor(circuit: fq.Circuit, term: PauliTerm, parameter: float) -> None:
    """Emit one Pauli rotation in the source's ordered first-order product."""
    axes = term.factors
    if not axes:
        raise ValueError("identity factors do not occur in the tapered excitations")
    wires = tuple(wire for wire, _ in axes)
    for wire, axis in axes:
        if axis == "y":
            circuit.sdg(wire)
        if axis in ("x", "y"):
            circuit.h(wire)
    for control in wires[:-1]:
        circuit.cx(control, wires[-1])
    circuit.rz(wires[-1], theta=2 * parameter * term.coefficient.real)
    for control in reversed(wires[:-1]):
        circuit.cx(control, wires[-1])
    for wire, axis in reversed(axes):
        if axis in ("x", "y"):
            circuit.h(wire)
        if axis == "y":
            circuit.s(wire)


def ansatz(
    width: int,
    hf_word: int,
    operators: tuple[PauliOperator, ...],
    parameters: tuple[float, ...],
) -> fq.Circuit:
    circuit = fq.Circuit(width, dtype=torch.complex128)
    for wire in range(width):
        if hf_word & (1 << (width - wire - 1)):
            circuit.x(wire)
    for operator, parameter in zip(operators, parameters, strict=True):
        for term in operator.terms:
            append_factor(circuit, term, parameter)
    return circuit


def check_ansatz(sectors: Sectors, operators: tuple[PauliOperator, ...]) -> float:
    width = sectors.reduction.n_qubits
    for operator in operators:
        assert all(
            pauli_words_commute(a, b)
            for a, b in itertools.combinations(operator.terms, 2)
        )
    spectra = tuple(
        torch.linalg.eigh(pauli_matrix(op, n_qubits=width)) for op in operators
    )
    errors = []
    for scale in (0.17, -0.23):
        parameters = tuple(
            scale * (i + 1) / len(operators) for i in range(len(operators))
        )
        actual = ansatz(width, sectors.hf_word, operators, parameters).state().flatten()
        reference = torch.zeros(2**width, dtype=torch.complex128)
        reference[sectors.hf_word] = 1
        for (values, vectors), parameter in zip(spectra, parameters, strict=True):
            reference = vectors @ (
                torch.exp(-1j * parameter * values) * (vectors.mH @ reference)
            )
        errors.append(float((actual - reference).abs().max()))
    error = max(errors)
    assert error < 3e-12, errors
    return error


def fit(sectors: Sectors) -> Optimization:
    operators = excitation_operators(sectors)
    error = check_ansatz(sectors, operators)
    width = sectors.reduction.n_qubits
    cost = trim(sectors.reduction.operator, THRESHOLD)
    matrix = pauli_matrix(cost, n_qubits=width)
    trace: list[Trial] = []

    def evaluate(point: torch.Tensor) -> torch.Tensor:
        if len(trace) == BUDGET:
            raise QueryBudgetError
        parameters = tuple(float(value) for value in point)
        state = ansatz(width, sectors.hf_word, operators, parameters).state().flatten()
        assert isinstance(state, torch.Tensor)
        value = torch.vdot(state, matrix @ state).real
        trace.append(Trial(float(value), parameters))
        return value

    converged = stopped = False
    try:
        result = CobylaOptimizer(maxiter=BUDGET, rhobeg=1.0, rhoend=1e-8).minimize(
            evaluate, torch.zeros(len(operators), dtype=torch.float64)
        )
        converged = result.converged
    except QueryBudgetError:
        stopped = True
    return Optimization(
        len(cost.terms),
        width,
        tuple(len(op.terms) for op in operators),
        tuple(trace),
        converged,
        stopped,
        error,
    )

"""Discover the active LiH diagonal symmetries and verify the compiled sectors."""

import itertools
import math
from dataclasses import dataclass

import torch

from flagquantum.algorithms.fermion.clifford import (
    pauli_words_commute,
    symplectic_masks,
)
from flagquantum.algorithms.fermion.encoding import encode_fermion
from flagquantum.algorithms.fermion.numerics import pauli_matrix
from flagquantum.algorithms.fermion.stabilizer import (
    StabilizerReduction,
    reduce_stabilizers,
)
from flagquantum.core.algebra.pauli import PauliOperator, pauli
from flagquantum.observables.fermion import FermionOperator

from .model import WIDTH

HF_WORD = (1 << (WIDTH - 1)) | (1 << (WIDTH - 2))


@dataclass(frozen=True)
class Sectors:
    hamiltonian: PauliOperator
    generators: tuple[PauliOperator, ...]
    dual_x: tuple[PauliOperator, ...]
    block: PauliOperator
    minima: tuple[tuple[tuple[int, ...], float], ...]
    hf_sector: tuple[int, ...]
    hf_word: int
    reduction: StabilizerReduction
    spectral_error: float


def trim(operator: PauliOperator, threshold: float) -> PauliOperator:
    return PauliOperator(
        tuple(t for t in operator.terms if abs(t.coefficient) > threshold)
    )


def diagonal_masks(operator: PauliOperator) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Enumerate the diagonal null space over GF(2) for the 10-wire source."""
    active = {symplectic_masks(term)[0] for term in operator.terms}
    rows: dict[int, int] = {}
    for number in range(1, 2**WIDTH):
        if any((number & flipped).bit_count() % 2 for flipped in active):
            continue
        remainder = number
        for pivot, row in sorted(rows.items()):
            if remainder & (1 << pivot):
                remainder ^= row
        if remainder:
            pivot = (remainder & -remainder).bit_length() - 1
            rows = {
                column: row ^ remainder if (row >> pivot) & 1 else row
                for column, row in rows.items()
            }
            rows[pivot] = remainder
    return tuple(rows[pivot] for pivot in sorted(rows)), tuple(sorted(rows))


def _z_eigenvalues(masks: tuple[int, ...], word: int) -> tuple[int, ...]:
    physical_bits = int(f"{word:0{WIDTH}b}"[::-1], 2)
    return tuple((-1) ** ((physical_bits & mask).bit_count() % 2) for mask in masks)


def analyze(fermion: FermionOperator) -> Sectors:
    h = trim(encode_fermion(fermion, n_modes=WIDTH).operator, 1e-13)
    masks, pivots = diagonal_masks(h)
    generators = tuple(
        pauli(factors=tuple((i, "z") for i in range(WIDTH) if (mask >> i) & 1))
        for mask in masks
    )
    dual_x = tuple(pauli(factors=((i, "x"),)) for i in pivots)
    transform = pauli()
    for i, (gen, x_op) in enumerate(zip(generators, dual_x, strict=True)):
        assert all(pauli_words_commute(gen.terms[0], term) for term in h.terms)
        for j, other in enumerate(generators):
            assert pauli_words_commute(x_op.terms[0], other.terms[0]) == (i != j)
        transform = transform * ((gen + x_op) * (1 / math.sqrt(2)))
    for gen, x_op in zip(generators, dual_x, strict=True):
        difference = trim(transform * gen * transform - x_op, 1e-12)
        assert not difference.terms
    block = trim(transform * h * transform, 1e-12)
    expected_sector = _z_eigenvalues(masks, HF_WORD)
    chosen = reduce_stabilizers(
        h, n_qubits=WIDTH, generators=generators, eigenvalues=expected_sector
    )
    h_dense = pauli_matrix(h, n_qubits=WIDTH)
    maxima = []
    minima = []
    for sector in itertools.product((1, -1), repeat=len(masks)):
        reduction = reduce_stabilizers(
            h, n_qubits=WIDTH, generators=generators, eigenvalues=sector
        )
        words = torch.tensor(
            [word for word in range(2**WIDTH) if _z_eigenvalues(masks, word) == sector],
            dtype=torch.long,
        )
        direct = h_dense.index_select(0, words).index_select(1, words)
        native = pauli_matrix(reduction.operator, n_qubits=reduction.n_qubits)
        reference = torch.linalg.eigvalsh(direct)
        spectrum = torch.linalg.eigvalsh(native)
        maxima.append(float((reference - spectrum).abs().max()))
        minima.append((sector, float(spectrum[0])))
    error = max(maxima)
    assert error < 2e-11
    word = HF_WORD
    for gate in chosen.clifford:
        assert gate.name == "cx"
        left, right = gate.wires
        if (word >> (WIDTH - left - 1)) & 1:
            word ^= 1 << (WIDTH - right - 1)
    reduced_hf = 0
    for index in chosen.mapping.free_qubits:
        reduced_hf = 2 * reduced_hf + ((word >> (WIDTH - index - 1)) & 1)
    return Sectors(
        h,
        generators,
        dual_x,
        block,
        tuple(minima),
        expected_sector,
        reduced_hf,
        chosen,
        error,
    )

"""Independent fixed-particle CI energy actions in spatial-orbital integrals."""

import numpy as np
import torch

import flagquantum as fq
from flagquantum.algorithms.fermion.lowering import lift_stabilizer_state
from flagquantum.algorithms.fermion.observables import to_observable
from flagquantum.core.algebra.pauli import PauliOperator

from . import model, variational


def energy(molecule: model.Model, full_state: torch.Tensor) -> float:
    """Map interleaved JW occupations to PySCF alpha/beta strings, retaining signs."""
    from pyscf.fci import cistring, direct_spin1

    strings = tuple(int(value) for value in cistring.make_strings(range(8), 5))
    ci = np.zeros((56, 56), dtype=np.complex128)
    for alpha_index, alpha in enumerate(strings):
        for beta_index, beta in enumerate(strings):
            word, parity = 0, 0
            for orbital in range(8):
                word |= ((alpha >> orbital) & 1) << (15 - 2 * orbital)
                word |= ((beta >> orbital) & 1) << (14 - 2 * orbital)
                if (beta >> orbital) & 1:
                    parity += (alpha >> (orbital + 1)).bit_count()
            ci[alpha_index, beta_index] = (-1) ** parity * complex(full_state[word])
    if abs(float(np.linalg.norm(ci)) - float(full_state.norm())) > 1e-12:
        raise ValueError(
            "The native state escaped the original five-alpha/five-beta space"
        )
    integrals = direct_spin1.absorb_h1e(
        molecule.one_body.numpy(), molecule.two_body.numpy(), 8, (5, 5), 0.5
    )
    # PySCF's real contraction supports real CI vectors; apply linearity explicitly.
    action = direct_spin1.contract_2e(integrals, ci.real.copy(), 8, (5, 5))
    action = action + 1j * direct_spin1.contract_2e(
        integrals, ci.imag.copy(), 8, (5, 5)
    )
    value = np.vdot(ci, action) + molecule.nuclear_energy * np.vdot(ci, ci)
    if abs(value.imag) > 1e-10:
        raise ValueError("The independent Hermitian energy has an imaginary residual")
    return float(value.real)


def check_energies(
    molecule: model.Model, generators: tuple[PauliOperator, ...]
) -> tuple[float, ...]:
    errors = []
    observable = to_observable(molecule.reduction.operator)
    for scale in (0.0, 0.17, -0.23):
        angles = tuple(scale * (index + 1) / 30 for index in range(30))
        program = variational.circuit(molecule, generators, angles)
        full = lift_stabilizer_state(molecule.reduction, program.state().reshape(-1))
        expected = energy(molecule, full)
        result = fq.run(program, outputs=[fq.expectation(observable)])
        actual = float(torch.as_tensor(result.expectation()).sum().real)
        errors.append(abs(actual - expected))
    if max(errors) > 1e-9:
        raise ValueError(
            "Native full-Hamiltonian energies disagree with independent CI contractions"
        )
    return tuple(errors)
